/* AP Biology CED (2019), Unit 2, topics 2.1–2.11, as requested by the course plan. Original teaching and questions.
   Framework: https://apstudents.collegeboard.org/sites/default/files/2019-05/ap-biology-course-and-exam-description.pdf
   Art is requested separately; numbers in models and experiments are fictional. */
const fig=(title,o)=>({t:'figure',title,...o});
const board=(title,lines,why=[])=>({t:'board',title,lines,why,box:true});
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const r4=v=>Math.round(v*1e4)/1e4;
const scenario=(title,p)=>{const lines=[];let line='';for(const word of p.split(' ')){if((line+' '+word).length>48){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return {t:'board',title,lines};};
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
const cube=(a,b)=>{const pts={},polys=[],segs=[],notes=[];[a,b].forEach((s,i)=>{const x=i*(a+b+3),y=0,k=i;for(const [n,u,v] of [['A',0,0],['B',s,0],['C',s,s],['D',0,s],['E',s*.4,s*.4],['F',s*1.4,s*.4],['G',s*1.4,s*1.4],['H',s*.4,s*1.4]])pts[n+k]=[x+u,y+v];polys.push({v:`A${k}B${k}C${k}D${k}`,col:i},{v:`D${k}C${k}G${k}H${k}`,col:i},{v:`B${k}F${k}G${k}C${k}`,col:i});notes.push({at:[x+s*.6,-b*.3],text:`side ${s} µm`});});return fig('Fictional cubes: same scale; depth shown obliquely',{pts,polys,segs,notes,dots:'',hide:Object.keys(pts).join(''),view:[-1,a+b+3+b*1.4+1,-b*.6,b*1.7]});};
const membrane=(mode='structure')=>{const pts={},circles=[],segs=[],polys=[],notes=[];for(let i=0;i<13;i++){if(i===6||i===7)continue;const x=i*1.1;for(const [n,y] of [['U',2],['L',-2]]){pts[n+i]=[x,y];circles.push({c:n+i,r:.3,col:0});const d=n==='U'?-1:1;for(let j=0;j<2;j++){const a=`${n}${i}${j}1`,b=`${n}${i}${j}2`;pts[a]=[x+(j-.5)*.22,y+d*.3];pts[b]=[x+(j-.5)*.22,y+d*1.6];segs.push({v:a+b,col:1,w:2});}}}Object.assign(pts,{A:[6,-2.4],B:[6.5,-2.4],C:[6.5,2.4],D:[6,2.4],E:[7.7,-2.4],F:[8.2,-2.4],G:[8.2,2.4],H:[7.7,2.4]});if(mode==='active')polys.push({v:'AFGD',col:3});else polys.push({v:'ABCD',col:3},{v:'EFGH',col:3});if(mode==='structure')notes.push({at:[3,3.4],text:'water + polar heads'},{at:[3,-3.4],text:'water + polar heads'},{at:[3,0],text:'nonpolar tails'},{at:[10.3,3.4],text:'protein channel'});else{pts.I=[mode==='simple'?3:7.1,3.4];pts.J=[pts.I[0],-3.4];segs.push({v:mode==='active'?'JI':'IJ',arrows:1,col:2,w:4});notes.push({at:[3,4.3],text:mode==='active'?'high solute':'high solute / O₂'},{at:[3,-4.3],text:'low solute'},{at:[11,0],text:mode==='active'?'energy input':'selective pore'});}return fig(mode==='structure'?'Fluid mosaic: lipid bilayer and embedded protein':mode==='active'?'Active transport: low → high (schematic pump)':'Passive transport: net movement down a gradient',{pts,hide:Object.keys(pts).join(''),dots:'',circles,segs,polys,notes,view:[-1,15,-5,5]});};
const flow=(title,labels)=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((s,i)=>{const x=i*5;Object.assign(pts,{['A'+i]:[x,0],['B'+i]:[x+4,0],['C'+i]:[x+4,2],['D'+i]:[x,2]});polys.push({v:`A${i}B${i}C${i}D${i}`,col:i%4});notes.push({at:[x+2,1],text:s});if(i){pts['E'+i]=[x-1,1];pts['F'+i]=[x,1];segs.push({v:'E'+i+'F'+i,arrows:1,col:0});}});return fig(title,{pts,polys,segs,notes,dots:'',hide:Object.keys(pts).join(''),view:[-1,labels.length*5,-2,4]});};
const tube=()=>fig('Osmosis: initial equal levels; solute cannot cross',{pts:{A:[0,5],B:[0,0],C:[10,0],D:[10,5],E:[2,5],F:[2,2],G:[8,2],H:[8,5],I:[0,3.5],J:[2,3.5],K:[8,3.5],L:[10,3.5],M:[5,0],N:[5,2],P:[3,1],Q:[7,1],S:[1,1],T:[9,1],U:[9,2.8],V:[8.8,2.1]},hide:'ABCDEFGHIJKLMNOPQSTUV',dots:'',segs:[{v:'AB',col:0},{v:'BC',col:0},{v:'CD',col:0},{v:'EF',col:0},{v:'FG',col:0},{v:'GH',col:0},{v:'IJ',col:0},{v:'KL',col:0},{v:'MN',col:3,dash:true},{v:'PQ',col:2,arrows:1}],circles:[{c:'S',r:.15,col:1},{c:'T',r:.15,col:1},{c:'U',r:.15,col:1},{c:'V',r:.15,col:1}],notes:[{at:[1,6],text:'less solute'},{at:[9,6],text:'more solute'},{at:[5,-1],text:'water crosses membrane →'}],view:[-3,13,-2,7]});
