const cell=plant=>[{t:'art',title:plant?'A photosynthetic plant cell':'An animal cell: subcellular components',items:[{src:`bio/${plant?'plant':'animal'}-cell.png`,x:320,y:223,h:160,label:plant?'cell wall outside the plasma membrane':'plasma membrane encloses cytoplasm',alt:plant?'Plant cell with a cell wall, a large central vacuole, chloroplasts and a nucleus':'Animal cell with a nucleus, rough ER, mitochondria and other organelles'}]},fig('',plant?{pts:{A:[121,129],B:[211,119],C:[441,154],D:[291,119],E:[431,34],F:[344,71]},segs:[{v:'AB',col:3},{v:'CD',col:2},{v:'EF',col:1}],notes:[{at:[76,129],text:'nucleus'},{at:[486,154],text:'large vacuole'},{at:[481,34],text:'chloroplast'}],hide:'ABCDEF',dots:'',view:[0,552,0,192]}
 :{pts:{A:[121,89],B:[256,99],C:[436,144],D:[321,127],E:[431,34],F:[316,57]},segs:[{v:'AB',col:3},{v:'CD',col:2},{v:'EF',col:1}],notes:[{at:[76,89],text:'nucleus'},{at:[476,144],text:'rough ER'},{at:[481,34],text:'mitochondrion'}],hide:'ABCDEF',dots:'',view:[0,552,0,192]})];
